import React, { useState, useRef, useEffect } from 'react';
import { Send, Volume2, Languages, ThumbsUp, ThumbsDown, Sparkles } from 'lucide-react';
import VoiceRecorder from './VoiceRecorder';
import { textToSpeech, translateText, submitFeedback } from '../services/api';

const ChatBox = ({ messages, onSendMessage, selectedLang, username, languages }) => {
  const [input, setInput] = useState('');
  const [playingMsgId, setPlayingMsgId] = useState(null);
  const [translatedMap, setTranslatedMap] = useState({});
  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handlePlayAudio = async (msgId, text, lang) => {
    setPlayingMsgId(msgId);
    try {
      const audioUrl = await textToSpeech(text, lang || selectedLang);
      const audio = new Audio(audioUrl);
      audio.onended = () => setPlayingMsgId(null);
      await audio.play();
    } catch (e) {
      console.error("Audio playback error:", e);
      setPlayingMsgId(null);
    }
  };

  const handleToggleTranslate = async (msgId, text) => {
    if (translatedMap[msgId]) {
      const newMap = { ...translatedMap };
      delete newMap[msgId];
      setTranslatedMap(newMap);
      return;
    }

    try {
      const res = await translateText(text, 'en');
      setTranslatedMap(prev => ({ ...prev, [msgId]: res.translated_text }));
    } catch (e) {
      console.error("Translation error:", e);
    }
  };

  const handleFeedback = async (msgId, rating) => {
    try {
      await submitFeedback(msgId, username, rating);
    } catch (e) {
      console.error("Feedback submission error:", e);
    }
  };

  return (
    <div className="glass-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column', height: '100%', overflow: 'hidden' }}>
      {/* Header */}
      <div style={{ padding: '16px 24px', borderBottom: '1px solid rgba(255, 255, 255, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ width: '10px', height: '10px', borderRadius: '50%', background: '#10b981', boxShadow: '0 0 10px #10b981' }} />
          <div>
            <h3 style={{ fontSize: '16px', fontWeight: 600, color: '#fff' }}>Multilingual Conversation</h3>
            <p style={{ fontSize: '12px', color: '#94a3b8' }}>Target: {languages[selectedLang]?.name || selectedLang}</p>
          </div>
        </div>
        <span className="badge-tag">51 Languages Active</span>
      </div>

      {/* Message List */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '20px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
        {messages.length === 0 ? (
          <div style={{ margin: 'auto', textAlign: 'center', color: '#94a3b8', maxWidth: '400px' }}>
            <Sparkles size={40} color="#8b5cf6" style={{ marginBottom: '12px' }} />
            <h4 style={{ color: '#fff', marginBottom: '8px' }}>Start a Multilingual Conversation</h4>
            <p style={{ fontSize: '13px' }}>Type or speak in any language. Matholy automatically detects your language, translates, and replies naturally.</p>
          </div>
        ) : (
          messages.map((msg, idx) => {
            const isUser = msg.sender === 'user';
            const isRTL = languages[msg.detected_language]?.dir === 'rtl';

            return (
              <div 
                key={idx}
                style={{
                  alignSelf: isUser ? 'flex-end' : 'flex-start',
                  maxWidth: '75%',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: isUser ? 'flex-end' : 'flex-start'
                }}
              >
                <div style={{ fontSize: '11px', color: '#94a3b8', marginBottom: '4px', display: 'flex', gap: '6px' }}>
                  <span>{isUser ? 'You' : 'Matholy AI'}</span>
                  {msg.detected_language && <span style={{ color: '#c084fc' }}>({msg.detected_language.toUpperCase()})</span>}
                </div>

                <div 
                  style={{
                    padding: '14px 18px',
                    borderRadius: isUser ? '20px 20px 4px 20px' : '20px 20px 20px 4px',
                    background: isUser 
                      ? 'linear-gradient(135deg, #3b82f6, #6366f1)' 
                      : 'rgba(30, 41, 59, 0.85)',
                    border: isUser ? 'none' : '1px solid rgba(255, 255, 255, 0.1)',
                    color: '#fff',
                    fontSize: '14px',
                    lineHeight: '1.5',
                    direction: isRTL ? 'rtl' : 'ltr',
                    textAlign: isRTL ? 'right' : 'left'
                  }}
                >
                  {msg.content}

                  {translatedMap[msg.id || idx] && (
                    <div style={{ marginTop: '10px', paddingTop: '8px', borderTop: '1px dashed rgba(255, 255, 255, 0.2)', fontSize: '13px', color: '#cbd5e1' }}>
                      <strong>EN:</strong> {translatedMap[msg.id || idx]}
                    </div>
                  )}
                </div>

                {/* Message Actions */}
                {!isUser && (
                  <div style={{ display: 'flex', gap: '10px', marginTop: '6px' }}>
                    <button 
                      onClick={() => handlePlayAudio(msg.id || idx, msg.content, msg.detected_language)}
                      style={{ background: 'none', border: 'none', color: playingMsgId === (msg.id || idx) ? '#ec4899' : '#94a3b8', cursor: 'pointer' }}
                      title="Listen to pronunciation"
                    >
                      <Volume2 size={15} />
                    </button>
                    <button 
                      onClick={() => handleToggleTranslate(msg.id || idx, msg.content)}
                      style={{ background: 'none', border: 'none', color: '#94a3b8', cursor: 'pointer' }}
                      title="Translate to English"
                    >
                      <Languages size={15} />
                    </button>
                    <button 
                      onClick={() => handleFeedback(msg.id || idx, 1)}
                      style={{ background: 'none', border: 'none', color: '#94a3b8', cursor: 'pointer' }}
                      title="Good response"
                    >
                      <ThumbsUp size={14} />
                    </button>
                    <button 
                      onClick={() => handleFeedback(msg.id || idx, -1)}
                      style={{ background: 'none', border: 'none', color: '#94a3b8', cursor: 'pointer' }}
                      title="Needs improvement"
                    >
                      <ThumbsDown size={14} />
                    </button>
                  </div>
                )}
              </div>
            );
          })
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input Area */}
      <div style={{ padding: '16px', borderTop: '1px solid rgba(255, 255, 255, 0.1)', display: 'flex', alignItems: 'center', gap: '12px' }}>
        <VoiceRecorder onTranscribe={(text) => onSendMessage(text)} selectedLang={selectedLang} />
        <input 
          type="text"
          placeholder="Write in English, Spanish, Hindi, Chinese, Swahili, Arabic..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          style={{
            flex: 1,
            background: 'rgba(255, 255, 255, 0.06)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '12px',
            padding: '12px 16px',
            color: '#fff',
            fontSize: '14px',
            outline: 'none'
          }}
        />
        <button onClick={handleSend} className="glow-btn" style={{ padding: '12px 18px', borderRadius: '12px' }}>
          <Send size={18} />
        </button>
      </div>
    </div>
  );
};

export default ChatBox;
